package com.learnagent.quiz;import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.JpaRepository;public interface AnswerRecordRepository extends JpaRepository<AnswerRecord,UUID>{boolean existsByQuizId(UUID quizId);List<AnswerRecord> findByQuizIdOrderByAnsweredAtAsc(UUID quizId);List<AnswerRecord> findByCourseId(UUID courseId);List<AnswerRecord> findAllByCourseIdIn(Collection<UUID> ids);List<AnswerRecord> findByAnsweredAtGreaterThanEqualAndAnsweredAtLessThan(Instant start,Instant end);default List<AnswerRecord>findByAnsweredAtGreaterThanEqualAndLessThan(Instant start,Instant end){return findByAnsweredAtGreaterThanEqualAndAnsweredAtLessThan(start,end);}long countByCorrect(boolean correct);}
